import numpy as np
import random
import torch
from typing import Dict, List, Optional, Union, Tuple

TAG_TIME = ["Dawn/Dusk", "Day", "Night"]
TAG_WEATHER = ["rain", "sunny"]
TAG_LOCATION = ["location_other", "location_phx", "location_sf"]

ALL_TAG_GROUPS = {
    "time_of_day": TAG_TIME,
    "weather": TAG_WEATHER,
    "location": TAG_LOCATION
}


def get_tag_vocab(selected_types: List[str]) -> List[str]:
    vocab = []
    for tag_type in selected_types:
        if tag_type in ALL_TAG_GROUPS:
            vocab.extend(ALL_TAG_GROUPS[tag_type])
    return vocab


def get_tag_channel_count(selected_types: List[str]) -> int:
    return len(get_tag_vocab(selected_types))


def encode_tags_onehot(tags_dict: Dict[str, str], selected_types: List[str]) -> np.ndarray:
    vocab = get_tag_vocab(selected_types)
    onehot = np.zeros(len(vocab), dtype=np.float32)
    
    idx = 0
    for tag_type in selected_types:
        if tag_type not in ALL_TAG_GROUPS:
            idx += len(ALL_TAG_GROUPS.get(tag_type, []))
            continue
            
        tag_values = ALL_TAG_GROUPS[tag_type]
        tag_value = tags_dict.get(tag_type)
        
        if tag_value in tag_values:
            onehot[idx + tag_values.index(tag_value)] = 1.0
        idx += len(tag_values)
    
    return onehot


def prepare_tag_conditioning(tags_batch: Union[List[Dict[str, str]], Dict[str, str]], 
                            spatial_shape: Tuple[int, int, int, int, int],
                            device: str,
                            selected_types: List[str]) -> torch.Tensor:
    if isinstance(tags_batch, dict):
        tags_batch = [tags_batch]
    
    B = len(tags_batch)
    D, H, W = spatial_shape[2], spatial_shape[3], spatial_shape[4]
    
    tag_tensors = []
    for tags_dict in tags_batch:
        onehot = encode_tags_onehot(tags_dict, selected_types)
        onehot_tensor = torch.from_numpy(onehot).float().to(device)
        tag_tensors.append(onehot_tensor)
    
    tags_stacked = torch.stack(tag_tensors, dim=0)
    C = tags_stacked.shape[1]
    return tags_stacked.view(B, C, 1, 1, 1).expand(B, C, D, H, W)


def resolve_tag_dict(
    user_tags: Optional[Dict[str, str]],
    tag_config,
    use_random_defaults: bool = True
) -> Dict[str, str]:
    """Resolve final tag dictionary with defaults/validation.
    
    Args:
        user_tags: User-provided tags (can be partial or None)
        tag_config: Config object with .types attribute
        use_random_defaults: Fill missing tags randomly vs skip
    
    Returns:
        Complete tag dict with all required types filled
    """
    if user_tags is None:
        user_tags = {}
    
    result = {}
    for tag_type in tag_config.types:
        if tag_type in user_tags:
            value = user_tags[tag_type]
            if tag_type in ALL_TAG_GROUPS and value in ALL_TAG_GROUPS[tag_type]:
                result[tag_type] = value
            else:
                valid_values = ALL_TAG_GROUPS.get(tag_type, [])
                raise ValueError(f"Invalid tag {tag_type}={value}. Valid values: {valid_values}")
        elif use_random_defaults:
            result[tag_type] = random.choice(ALL_TAG_GROUPS[tag_type])
    
    return result


def parse_tag_arguments(coarse_tag, refine_tag):
    # Parse coarse tags (for coarse generation)
    coarse_user_tags = {}
    if coarse_tag:
        for pair in coarse_tag:
            key, value = pair.split('=', 1)
            coarse_user_tags[key.strip()] = value.strip()
    
    # Parse refinement tags (for refinement levels)
    refine_user_tags = {}
    if refine_tag:
        for pair in refine_tag:
            key, value = pair.split('=', 1)
            refine_user_tags[key.strip()] = value.strip()

    return coarse_user_tags, refine_user_tags

